mapper.select:
SELECT id, user_id FROM teacher_binding_code
WHERE code_hash = #{codeHash}
  AND consumed_at IS NULL
  AND expires_at > #{now}

mapper.insert:
INSERT INTO wechat_identity (
  user_id, app_id, openid, unionid, created_at, last_login_at
) VALUES (
  #{userId}, #{appId}, #{openId}, #{unionId}, #{now}, #{now}
)

mapper.update:
UPDATE wechat_identity
SET unionid = COALESCE(#{unionId}, unionid), last_login_at = #{now}
WHERE app_id = #{appId} AND openid = #{openId}

mapper.select:
SELECT user_id FROM auth_session
WHERE token_hash = #{tokenHash}
  AND revoked_at IS NULL
  AND expires_at > #{now}
